using UnityEngine;
using UnityEngine.UI;
namespace Brodun.Presentation
{
    // Temporary, pixel-aligned UI symbols; numbers are always separate Text objects.
    [RequireComponent(typeof(CanvasRenderer))]
    public sealed class CardEffectGlyph:MaskableGraphic
    {
        public CardEffectSymbol Symbol {get;private set;}
        public void Set(CardEffectSymbol value){Symbol=value;raycastTarget=false;SetVerticesDirty();}
        public CardEffectGlyph(){useLegacyMeshGeneration=false;}
        private static readonly string[][] Patterns={
            new[]{"0000000000011000","0000000000111100","0000000001111100","0000000011111000","0000000111110000","0000001111100000","0000011111000000","0110111110000000","0111111100000000","0011111000000000","0001111110000000","0011110110000000","0111100000000000","1111000000000000","1110000000000000","0100000000000000"},
            new[]{"0001111111111000","0111111111111110","0110000000000110","0110001100000110","0110001100000110","0110001100000110","0110001100000110","0011001100001100","0011001100001100","0001101100011000","0001101100011000","0000110000110000","0000011001100000","0000001111000000","0000000110000000","0000000000000000"},
            new[]{"0001111111000000","0001000001000000","0001011111110000","0001010000010000","0001010111111100","0000010100000100","0000010100000100","0000000100000100","0000000100000100","0111000100000100","0111000111111100","0011000000000000","0011111110000000","0001111110000000","0000001100000000","0000011000000000"},
            new[]{"0011111110000000","0110000011000000","0110010011000000","0110010011000000","0011010110000000","0001111100000000","0000111000000000","0000010000000000","0000000000111000","0011000001111000","0110000000111000","0110000000011000","0111111111111000","0011111111110000","0000000000000000","0000000000000000"},
            new[]{"0111111000000110","0100001000001110","0101101000011100","0101101000111000","0101101001110000","0011110011100000","0001100111000000","0000001110000000","0000011100000000","0000111000000000","0011111110000000","0001101000000000","0011100000000000","0111000000000000","1110000000000000","0100000000000000"},
            new[]{"0011111111110000","0110001100011000","0110011000011000","0110110000011000","0110011100011000","0110001100011000","0011001000110000","0011010000110000","0001100001100000","0000110011000000","0000011110000000","0000001100000000","0000000000000000","0001111111110000","0001111111110000","0000000000000000"},
            new[]{"0011111111110000","0110000000011000","0110001100011000","0110001100011000","0110111111011000","0110111111011000","0011001100110000","0011001100110000","0001100001100000","0000110011000000","0000011110000000","0000001100000000","0011000000110000","0011111111110000","0001111111100000","0000000000000000"},
            new[]{"0000001100000000","0000011110000000","0000110011000000","0001100001100000","0011000000110000","0001100001100000","0000110011000000","0000011110000000","0000001100000000","0000001100000000","0001111111110000","0001100000110000","0001100000110000","0011110001111000","0001100000110000","0000000000000000"}
        };
        protected override void OnPopulateMesh(VertexHelper vh)
        {
            vh.Clear();var r=rectTransform.rect;float unit=Mathf.Min(r.width,r.height)/16;var min=r.center-Vector2.one*unit*8;
            var grid=Patterns[(int)Symbol];
            for(int y=0;y<16;y++)for(int x=0;x<16;x++)if(grid[y][x]=='1')
            {
                var p=min+new Vector2(x,15-y)*unit;int i=vh.currentVertCount;
                vh.AddVert(p,color,Vector2.zero);vh.AddVert(p+new Vector2(0,unit),color,Vector2.zero);
                vh.AddVert(p+Vector2.one*unit,color,Vector2.zero);vh.AddVert(p+new Vector2(unit,0),color,Vector2.zero);
                vh.AddTriangle(i,i+1,i+2);vh.AddTriangle(i,i+2,i+3);
            }
        }
    }
}
